-- The venue calendar lists 254 A-C for KubeCon 2026. The schedule
-- abbreviates the location to 254, so resolve it to the full booked block.
INSERT INTO location_rooms (location_id, room_id)
SELECT locations.id, rooms.id
FROM (VALUES
    ('250 A-C', ARRAY['250A', '250B', '250C']),
    ('250 D-F', ARRAY['250D', '250E', '250F']),
    ('251 A-C', ARRAY['251A', '251B', '251C']),
    ('251 D-F', ARRAY['251D', '251E', '251F']),
    ('254', ARRAY['254A', '254B', '254C'])
) AS mapping (label, room_names)
JOIN locations ON locations.venue = 'Salt Palace'
    AND locations.level = 'Level 2'
    AND locations.room = mapping.label
JOIN rooms ON rooms.venue = locations.venue
    AND rooms.floor = 2
    AND rooms.name = ANY(mapping.room_names);
